style.content:
.gallery {
  /* display: grid-lanes; */
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Looks only, shared by all three pages. */

.stage {
  background: #f1eee7;
}

.scroll {
  position: absolute;
  inset: 0;
  padding: 1.4rem;
  overflow-y: auto;
}

.tile {
  margin: 0;
  overflow: hidden;
  background: #fff;
  border: 1px solid #e4dfd4;
  border-radius: 0.9rem;
  box-shadow: 0 14px 30px -22px rgb(28 27 34 / 0.55);
}

.tile img {
  display: block;
  width: 100%;
  height: auto;
}

.tile figcaption {
  padding: 0.6rem 0.8rem 0.7rem;
  font-size: 0.9rem;
  font-weight: 700;
}

.tile figcaption span {
  display: block;
  font-size: 0.8rem;
  font-weight: 400;
  color: #77748a;
}

/* "Load more" (more.js) */
.more {
  display: block;
  margin: 1.4rem auto 0.4rem;
  padding: 0.65rem 1.3rem;
  font: inherit;
  font-weight: 700;
  color: #4636c9;
  cursor: pointer;
  background: #fff;
  border: 1px solid #d9d4f7;
  border-radius: 999px;
}

script.hiddenContent:
/*
  Demo helper, the same on all three pages and not part of the comparison:
  "Load more" appends six more cards to the gallery, like infinite scroll.
*/
(function () {
  var MORE = [
    ['copper-canyon', 'Copper Canyon', 'Red walls at noon', 560],
    ['moonlit-pines', 'Moonlit Pines', 'A clear winter night', 380],
    ['sunlit-leaves', 'Sunlit Leaves', 'Late summer', 500],
    ['tidal-shapes', 'Tidal Shapes', 'Low tide patterns', 320],
    ['aurora-ridge', 'Aurora Ridge, again', 'The second night', 440],
    ['salt-dunes', 'Salt Dunes, again', 'Morning wind', 600]
  ];
  var gallery = document.querySelector('.gallery');
  var button = document.createElement('button');
  button.className = 'more';
  button.textContent = 'Load more';
  gallery.after(button);

  button.addEventListener('click', function () {
    MORE.forEach(function (m) {
      var tile = document.createElement('figure');
      tile.className = 'tile';
      tile.innerHTML = '<img alt="" width="400"><figcaption><span></span></figcaption>';
      var img = tile.querySelector('img');
      img.src = 'https://stepan-fielmann.github.io/wey/images/scenes/' + m[0] + '.svg';
      img.height = m[3];
      tile.querySelector('figcaption').prepend(m[1]);
      tile.querySelector('span').textContent = m[2];
      gallery.append(tile);
    });
  });
})();

// A small note in the preview when the browser lacks the feature a modern view shows.
// `support` comes from feature.js: { css: 'display: grid-lanes' } or { api: 'popover' }.
function showUnsupported(support) {
  const API = { popover: () => 'showPopover' in HTMLElement.prototype };
  const ok = support.api ? API[support.api]() : CSS.supports(support.css);
  if (ok) return;
  const note = document.createElement('p');
  note.className = 'unsupported';
  const name = document.createElement('b');
  name.textContent = support.feature;
  const text = document.createElement('span');
  text.append(name, ' isn’t supported in this browser.' + (support.hint ? ` ${support.hint}` : ''));
  note.append(text);
  (document.querySelector('.stage') ?? document.body).prepend(note);
}

showUnsupported({"feature":"CSS Grid Lanes","css":"display: grid-lanes","hint":"Use Safari 26.4+, or Chrome with “Experimental Web Platform features” on."});
